"use client";

/** Implements the reusable card grid, flip behaviour, match rules, and completion view for memory games. */
import Image from "next/image";
import { useEffect, useRef, useState } from "react";
import type { MemoryMatchManifest } from "./game-manifest";
import styles from "./memory-match-runtime.module.css";

type Card = { id: string; pairId: string; symbol: string; label: string; state: "down" | "up" | "matched" };

/**
 * What it does: Builds and shuffles two cards for each configured memory pair.
 * Can be generated by AI?: No.
 */
function createDeck(manifest: MemoryMatchManifest): Card[] {
  const cards = manifest.rules.pairs.flatMap((pair) => [0, 1].map((copy) => ({ id: `${pair.id}-${copy}`, pairId: pair.id, symbol: pair.symbol, label: pair.label, state: "down" as const })));
  for (let index = cards.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(Math.random() * (index + 1));
    [cards[index], cards[swapIndex]] = [cards[swapIndex], cards[index]];
  }
  return cards;
}

/**
 * What it does: Renders any Memory Match manifest with reusable flip and match interactions.
 * Can be generated by AI?: No.
 */
export function MemoryMatchRuntime({ manifest }: { manifest: MemoryMatchManifest }) {
  const [cards, setCards] = useState(() => createDeck(manifest));
  const [openCardIds, setOpenCardIds] = useState<string[]>([]);
  const [moves, setMoves] = useState(0);
  const [locked, setLocked] = useState(false);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const matchedPairs = cards.filter((card) => card.state === "matched").length / 2;
  const complete = matchedPairs === manifest.rules.pairs.length;

  useEffect(() => () => { if (timeoutRef.current) clearTimeout(timeoutRef.current); }, []);

  const flipCard = (cardId: string) => {
    if (locked || complete) return;
    const card = cards.find((item) => item.id === cardId);
    if (!card || card.state !== "down") return;
    const nextOpenIds = [...openCardIds, cardId];
    const nextCards = cards.map((item) => item.id === cardId ? { ...item, state: "up" as const } : item);
    setCards(nextCards);

    if (nextOpenIds.length < 2) {
      setOpenCardIds(nextOpenIds);
      return;
    }

    setMoves((count) => count + 1);
    setOpenCardIds([]);
    const first = nextCards.find((item) => item.id === nextOpenIds[0]);
    const second = nextCards.find((item) => item.id === nextOpenIds[1]);
    if (first?.pairId === second?.pairId) {
      setCards(nextCards.map((item) => nextOpenIds.includes(item.id) ? { ...item, state: "matched" as const } : item));
      return;
    }

    setLocked(true);
    timeoutRef.current = setTimeout(() => {
      setCards((current) => current.map((item) => nextOpenIds.includes(item.id) ? { ...item, state: "down" as const } : item));
      setLocked(false);
    }, manifest.rules.mismatchDelayMs);
  };

  const restart = () => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    setCards(createDeck(manifest));
    setOpenCardIds([]);
    setMoves(0);
    setLocked(false);
  };

  return (
    <section className={styles.game} style={{ background: manifest.theme.pageBackground, color: manifest.theme.textColor }} aria-label={manifest.metadata.title}>
      <div className={styles.content}>
        <p className={styles.eyebrow}>MEMORY MATCH</p>
        <h1>{manifest.metadata.title}</h1>
        <p>{manifest.metadata.instructions}</p>
        <div className={styles.stats}><span>Moves: {moves}</span><span>Pairs: {matchedPairs}/{manifest.rules.pairs.length}</span></div>
        <div className={styles.grid}>
          {cards.map((card) => <button key={card.id} type="button" className={`${styles.card} ${card.state !== "down" ? styles.revealed : ""} ${card.state === "matched" ? styles.matched : ""}`} onClick={() => flipCard(card.id)} aria-label={card.state === "down" ? "Reveal card" : card.label}>
            {card.state === "down" ? <Image src={manifest.assets.cardBack} alt="" fill sizes="120px" /> : <span aria-hidden="true">{card.symbol}</span>}
          </button>)}
        </div>
        {complete && <div className={styles.result}><strong>All pairs matched in {moves} moves!</strong><button type="button" onClick={restart} style={{ background: manifest.theme.accentColor }}>Play again</button></div>}
      </div>
    </section>
  );
}
